CREATE OR REPLACE PROCEDURE PRAXIS.PX161S02A1820 ( IN IN_ACTION CHAR(1),
                                        IN IN_A1820CCUST VARCHAR(3),
                                        IN IN_A1820TCUAT VARCHAR(20),
                                        IN IN_A1820DESCR VARCHAR(100),
                                        IN IN_A1820CLIEN VARCHAR(10),
                                        IN IN_A1820DIREC VARCHAR(20),
                                        IN IN_A1820TIPO VARCHAR(10),
                                        IN IN_A1820DOCU VARCHAR(15),
                                        IN IN_A1820CIA CHAR(2),
                                        IN IN_A1820UNID CHAR(2),--READ ONLY
                                        IN IN_A1820CECO CHAR(7),
                                        IN IN_A1820UBI CHAR(4),
                                        IN IN_A1820CTA CHAR(6), -- REESTRUCTURACION CONTABLE 
                                        IN IN_A1820SCTA CHAR(5),
                                        IN IN_A1820EQUI CHAR(4),
                                        IN IN_A1820ICIA CHAR(2),
                                        IN IN_A1820FINI VARCHAR(8),
                                        IN IN_A1820FFIN VARCHAR(8),
                                        IN IN_USR VARCHAR(10),
                                        IN IN_FEC VARCHAR(8),
                                        IN IN_HOR VARCHAR(6),
                                        IN IN_A1820MODO CHAR(1),
                                        IN IN_A1820TCUAT_OLD VARCHAR(20) )
	RESULT SETS 1
	LANGUAGE SQL
	SPECIFIC PRAXIS.PX161S02A1820

BEGIN DECLARE VL_SQLCODE INTEGER DEFAULT 0 ; DECLARE SQLCODE INTEGER DEFAULT 0 ; DECLARE VL_MESSAGE VARCHAR ( 100 ) DEFAULT NULL ; DECLARE CURQRY CURSOR FOR SELECT VL_MESSAGE AS VMESSAGE , VL_SQLCODE AS VSQLCODE FROM ( VALUES ( '' , 0 ) ) AS TBL ; DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET VL_SQLCODE = REPLACE ( SQLCODE , '-' , '' ) ; IF IN_ACTION = 'I' THEN IF NOT EXISTS ( SELECT 0 FROM PRAXIS . A1820 WHERE A1820TCUAT = IN_A1820TCUAT ) THEN INSERT INTO PRAXIS . A1820 ( A1820CCUST , A1820TCUAT , A1820DESCR , A1820CLIEN , A1820DIREC , A1820TIPO , A1820DOCU , A1820CIA , A1820UNID , A1820CECO , A1820UBI , A1820CTA , A1820SCTA , A1820EQUI , A1820ICIA , A1820FINI , A1820FFIN , A1820REGIS , A1820FREGI , A1820HREGI , A1820REGVI , A1820FREVI , A1820HREVI , A1820MODO ) VALUES ( IN_A1820CCUST , IN_A1820TCUAT , IN_A1820DESCR , IN_A1820CLIEN , IN_A1820DIREC , IN_A1820TIPO , IN_A1820DOCU , IN_A1820CIA , IN_A1820UNID , IN_A1820CECO , IN_A1820UBI , IN_A1820CTA , IN_A1820SCTA , IN_A1820EQUI , IN_A1820ICIA , IN_A1820FINI , IN_A1820FFIN , IN_USR , IN_FEC , IN_HOR , '' , '' , '' , IN_A1820MODO ) ; SET VL_MESSAGE = 'RECORD INSERTED' ; OPEN CURQRY ; ELSE SET VL_MESSAGE = 'RECORD EXISTS' ; OPEN CURQRY ; END IF ; END IF ; IF IN_ACTION = 'U' THEN IF NOT EXISTS ( SELECT 0 FROM PRAXIS . A1820 WHERE ( A1820TCUAT = IN_A1820TCUAT ) AND ( A1820TCUAT <> IN_A1820TCUAT_OLD ) ) THEN UPDATE PRAXIS . A1820 SET ( A1820TCUAT , A1820DESCR , A1820CLIEN , A1820DIREC , A1820TIPO , A1820DOCU , A1820CIA , A1820UNID , A1820CECO , A1820UBI , A1820CTA , A1820SCTA , A1820EQUI , A1820ICIA , A1820FINI , A1820FFIN , A1820REGVI , A1820FREVI , A1820HREVI , A1820MODO ) = ( IN_A1820TCUAT , IN_A1820DESCR , IN_A1820CLIEN , IN_A1820DIREC , IN_A1820TIPO , IN_A1820DOCU , IN_A1820CIA , IN_A1820UNID , IN_A1820CECO , IN_A1820UBI , IN_A1820CTA , IN_A1820SCTA , IN_A1820EQUI , IN_A1820ICIA , IN_A1820FINI , IN_A1820FFIN , IN_USR , IN_FEC , IN_HOR , IN_A1820MODO ) WHERE A1820CCUST = IN_A1820CCUST AND A1820TCUAT = IN_A1820TCUAT_OLD ; SET VL_MESSAGE = 'RECORD UPDATED' ; OPEN CURQRY ; ELSE SET VL_MESSAGE = 'RECORD EXISTS' ; OPEN CURQRY ; END IF ; END IF ; IF IN_ACTION = 'D' THEN DELETE FROM PRAXIS . A1820 WHERE A1820CCUST = IN_A1820CCUST AND A1820TCUAT = IN_A1820TCUAT_OLD ; SET VL_MESSAGE = 'RECORD REMOVED' ; OPEN CURQRY ; END IF ; /* CONTROL DE ERRORES */ IF ( VL_SQLCODE <> 0 ) THEN SELECT DB_MESSAGE INTO VL_MESSAGE FROM PRAXIS . INF054 WHERE DB_SQLCODE = VL_SQLCODE ; IF VL_MESSAGE IS NULL THEN SET VL_MESSAGE = 'AN UNEXPECTED ERROR OCCURRED, CODE ' CONCAT VL_SQLCODE ; END IF ; ELSE SET VL_MESSAGE = 'OPERATION WAS SUCCESSFUL' ; END IF ; OPEN CURQRY ; END